SELECT owner_type, owner_id, SUM(ticket_price) AS totalTicketPrice, -- 总票价 AVG(ticket_price) AS avgTicketPrice, -- 平均票价 MAX(ticket_price) AS maxTicketPrice, -- 最高票价 MIN(ticket_price) AS minTicketPrice, -- 最低票价 COUNT(*) AS recordCount -- 记录总数 FROM cms_registration
AND owner_type = #{ownerType}
AND owner_id = #{ownerId}
AND registration_status = #{registrationStatus}
GROUP BY owner_type, owner_id
ORDER BY totalTicketPrice DESC

